export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"id","term":"Ethereum (ETH)","aka":["ETH","Ether"],"short":"Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking.","body":[["Berbeda dengan ",["Bitcoin","bitcoin"]," yang fokus sebagai uang digital, Ethereum dirancang sebagai platform. Pengembang bisa menulis ",["smart contract","smart-contract"],", yaitu program yang berjalan otomatis di ",["blockchain","blockchain"],". Dari sinilah lahir ",["DeFi","defi"],", ",["NFT","nft"],", ",["stablecoin","stablecoin"]," berbasis token, dan banyak aplikasi lain."],"Setiap aksi di Ethereum, dari transfer sampai swap, membutuhkan biaya gas yang dibayar dalam ETH. Saat jaringan ramai, biaya gas bisa naik tajam. Karena itu banyak pengguna memakai jaringan layer 2 seperti Arbitrum, Optimism, atau Base yang lebih murah namun tetap menyandarkan keamanannya pada Ethereum.","Pada September 2022, Ethereum beralih dari proof of work ke proof of stake lewat peristiwa yang disebut The Merge. Sekarang validator mengunci ETH sebagai jaminan untuk mengamankan jaringan dan mendapat imbalan staking."],"example":"Misalkan Anda ingin menukar token di aplikasi DeFi di jaringan utama Ethereum. Transaksi Anda memakai 150.000 unit gas, dan harga gas saat itu 20 gwei. Biayanya 150.000 x 20 = 3.000.000 gwei, atau 0,003 ETH. Jika ETH bernilai 3.000 USDT, biaya transaksi sekitar 9 USDT. Transaksi yang sama di layer 2 biasanya hanya memakan sebagian kecil dari itu.","mistakes":["Tidak menyisakan sedikit ETH di dompet, sehingga token lain di jaringan Ethereum tidak bisa dipindahkan karena tidak ada saldo untuk gas.","Mengira ETH di jaringan Arbitrum atau Base bisa langsung dikirim ke alamat yang hanya mendukung jaringan utama tanpa memeriksa jaringannya.","Menyamakan Ethereum dengan Ethereum Classic, padahal keduanya blockchain yang berbeda."],"faq":[{"q":"Apa beda Ethereum dan ETH?","a":"Ethereum adalah nama jaringannya, sedangkan ETH adalah koin aslinya. ETH dipakai untuk membayar biaya gas dan untuk staking."},{"q":"Apakah Ethereum masih ditambang?","a":"Tidak. Sejak The Merge pada September 2022, Ethereum memakai proof of stake, sehingga blok dibuat oleh validator, bukan penambang."}],"title":"Apa itu Ethereum (ETH)? Arti dan fungsinya","description":"Pelajari apa itu Ethereum, fungsi ETH untuk biaya gas dan staking, peran smart contract, dan kenapa layer 2 lebih murah.","related":[["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya."],["layer-2","Layer 2 (L2)","Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah."],["defi","DeFi (keuangan terdesentralisasi)","DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"id","term":"Layer 1 (L1)","aka":["L1","blockchain layer 1"],"short":"Layer 1 (L1) adalah blockchain dasar yang memproses dan memfinalisasi transaksinya sendiri dengan mekanisme konsensus dan koin aslinya, seperti Bitcoin, Ethereum, dan Solana.","body":[["Disebut layer 1 karena ia lapisan paling dasar. Keamanan, pencatatan transaksi, dan aturan jaringannya diatur langsung di ",["blockchain","blockchain"]," itu. Setiap L1 punya coin asli untuk membayar biaya, misalnya ",["BTC","bitcoin"],", ",["ETH","ethereum"],", SOL, atau BNB."],["Setiap L1 membuat pilihan desain berbeda antara desentralisasi, keamanan, dan kecepatan. Bitcoin memprioritaskan keamanan dan kesederhanaan. Ethereum mendukung ",["smart contract","smart-contract"]," dan mengandalkan ",["layer 2","layer-2"]," untuk skala. Solana mengejar kecepatan tinggi di satu lapisan dengan kebutuhan perangkat keras yang lebih besar."],["Bagi pengguna, perbedaan L1 terasa dari biaya, kecepatan ",["konfirmasi","block-confirmations"],", dompet yang didukung, dan format alamat. Alamat di satu L1 umumnya tidak bisa menerima aset dari L1 lain secara langsung, sehingga perpindahan antarjaringan memerlukan bridge atau exchange."]],"example":"Misalkan Anda ingin memindahkan 100 USDT. Di sebuah L1 dengan biaya rendah, transfer mungkin hanya memakan biaya di bawah 0,01 USDT dan selesai dalam beberapa detik. Di jaringan utama Ethereum saat ramai, transfer token yang sama bisa memakan beberapa dolar. Jika biaya 3 USDT, itu sudah 3% dari dana Anda, sehingga memilih jaringan yang tepat sangat berpengaruh untuk jumlah kecil.","mistakes":["Mengira semua L1 kompatibel, lalu mengirim aset ke alamat di jaringan yang berbeda.","Menilai L1 hanya dari kecepatan transaksi tanpa melihat tingkat desentralisasi dan riwayat gangguan jaringan.","Lupa menyiapkan coin asli L1 untuk biaya transaksi."],"faq":[{"q":"Apa beda layer 1 dan layer 2?","a":"Layer 1 adalah blockchain dasar dengan keamanannya sendiri. Layer 2 dibangun di atas L1 untuk memproses transaksi lebih murah, lalu menyetor hasilnya kembali ke L1."},{"q":"Apakah BNB Chain termasuk layer 1?","a":"Ya, BNB Smart Chain adalah blockchain dengan konsensus dan koin aslinya sendiri, yaitu BNB, sehingga umumnya digolongkan sebagai layer 1."}],"title":"Apa itu layer 1 (L1) di kripto? Arti dan contoh","description":"Pelajari arti layer 1, contoh blockchain L1 seperti Bitcoin dan Solana, dan kenapa pilihan jaringan memengaruhi biaya Anda.","related":[["layer-2","Layer 2 (L2)","Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."],["ethereum","Ethereum (ETH)","Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking."],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."],["coin-vs-token","Coin vs token","Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"id","term":"Token burn","aka":["burn","pembakaran token","burning"],"short":"Token burn adalah penghapusan permanen sejumlah token dari peredaran dengan mengirimnya ke alamat yang tidak bisa diakses siapa pun, sehingga total suplai berkurang.","body":[["Burn dilakukan dengan mengirim token ke alamat burn, yaitu alamat yang tidak punya ",["private key","private-key"],", atau lewat fungsi burn di ",["smart contract","smart-contract"],". Karena tidak ada yang bisa memindahkannya lagi, token itu dianggap hilang selamanya dan bisa diverifikasi di ",["block explorer","block-explorer"],"."],["Ada beberapa model burn. BNB memakai program burn berkala yang mengurangi suplainya. ",["Ethereum","ethereum"]," membakar base fee dari setiap transaksi sejak EIP-1559, sehingga suplai ETH bisa berkurang saat aktivitas jaringan tinggi. Proyek lain membakar sebagian pendapatan atau token yang dibeli kembali."],"Burn mengurangi suplai, tetapi tidak menjamin harga naik. Jika permintaan turun lebih cepat, harga tetap bisa melemah. Perhatikan juga apakah proyek sekaligus mencetak token baru yang jumlahnya lebih besar daripada yang dibakar."],"example":["Misalkan sebuah token memiliki ",["circulating supply","circulating-supply"]," 800 juta dan proyek membakar 16 juta token dalam satu kuartal, atau 2% suplai. Namun di periode yang sama, hadiah ",["staking","staking"]," menambah 24 juta token baru. Hasil bersihnya suplai bertambah 8 juta token, menjadi 808 juta. Jadi meski ada pengumuman burn, tokenomics ini tetap inflasioner pada kuartal itu."],"mistakes":["Mengira setiap pengumuman burn otomatis membuat harga naik.","Tidak memeriksa bukti burn di block explorer.","Mengabaikan token baru yang dicetak bersamaan sehingga suplai bersih tetap naik."],"faq":[{"q":"Apakah token yang dibakar bisa dikembalikan?","a":"Tidak. Token yang dikirim ke alamat burn tanpa private key tidak bisa dipindahkan lagi oleh siapa pun."},{"q":"Kenapa proyek membakar token?","a":"Biasanya untuk mengurangi suplai, mengimbangi inflasi, atau mengembalikan nilai dari pendapatan protokol kepada pemegang token secara tidak langsung."}],"title":"Apa itu token burn? Arti pembakaran token","description":"Pelajari arti token burn, cara pembakaran token bekerja, contoh BNB dan ETH, dan kenapa burn tidak menjamin harga naik.","related":[["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai."],["circulating-supply","Circulating supply (suplai beredar)","Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan."],["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."],["coin-vs-token","Coin vs token","Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract."]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"id","term":"FUD (fear, uncertainty, doubt)","aka":["fear, uncertainty and doubt"],"short":"FUD adalah singkatan dari fear, uncertainty, and doubt, yaitu informasi atau rumor negatif yang menimbulkan rasa takut dan ragu sehingga mendorong orang menjual aset.","body":["FUD bisa berasal dari berita nyata, seperti peretasan exchange atau tindakan regulator, tetapi juga dari rumor yang dibesar-besarkan atau sengaja disebarkan. Di komunitas kripto, istilah ini kadang dipakai untuk menolak kritik yang sah, jadi jangan langsung menganggap semua kabar buruk sebagai FUD.",["Saat FUD menyebar, harga bisa turun tajam dalam waktu singkat karena banyak orang menjual bersamaan. Trader dengan ",["leverage","leverage"]," tinggi bisa terkena ",["likuidasi","liquidation"]," berantai, yang memperdalam penurunan."],["Cara menyikapinya adalah memeriksa sumber. Cari pengumuman resmi proyek atau exchange, periksa ",["data on-chain","on-chain-analysis"]," seperti arus dana keluar, dan bedakan fakta dari opini. Keputusan yang diambil setelah verifikasi biasanya lebih baik daripada reaksi panik."]],"example":["Misalkan beredar rumor bahwa sebuah exchange menghentikan penarikan. Dalam satu jam, token exchange itu turun 18% dari 5,00 menjadi 4,10 ",["USDT","usdt"],". Anda memegang 100 token senilai 500 USDT, yang kini bernilai 410 USDT. Jika rumornya ternyata salah dan harga kembali ke 4,80 USDT, menjual panik di 4,10 berarti mengunci rugi 90 USDT. Jika rumornya benar, menunggu juga bisa merugikan, jadi verifikasi sumber adalah langkah pertama."],"mistakes":["Menjual panik setelah membaca satu unggahan media sosial tanpa memeriksa sumber resmi.","Menyebut semua kritik sebagai FUD sehingga mengabaikan risiko nyata.","Memakai leverage tinggi saat berita negatif sedang beredar."],"faq":[{"q":"Apa arti FUD di kripto?","a":"FUD berarti fear, uncertainty, and doubt, yaitu kabar negatif yang menimbulkan rasa takut dan mendorong penjualan. Kabarnya bisa benar, dilebih-lebihkan, atau palsu."},{"q":"Bagaimana membedakan FUD dan berita nyata?","a":"Periksa sumber resmi, data on-chain, dan beberapa media terpercaya. Kabar yang hanya beredar dari akun anonim tanpa bukti layak diragukan."}],"title":"Apa itu FUD di kripto? Arti dan cara menyikapinya","description":"Pelajari arti FUD di kripto, kenapa kabar negatif bisa menjatuhkan harga, dan cara memverifikasi rumor sebelum bertindak.","related":[["fomo","FOMO (fear of missing out)","FOMO atau fear of missing out adalah rasa takut ketinggalan keuntungan yang mendorong trader membeli secara impulsif setelah harga sudah naik tajam."],["bear-market","Bear market (pasar bearish)","Bear market adalah periode ketika harga aset di pasar cenderung turun secara berkelanjutan, biasanya 20% atau lebih dari puncaknya, disertai sentimen pesimis dan volume yang menurun."],["fear-and-greed-index","Fear and Greed Index (indeks ketakutan dan keserakahan)","Fear and Greed Index adalah indikator sentimen pasar kripto berskala 0 sampai 100, di mana angka rendah menunjukkan ketakutan ekstrem dan angka tinggi menunjukkan keserakahan ekstrem."],["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya."},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"id","term":"Bid-ask spread (spread)","aka":["spread","selisih bid ask","spread harga"],"short":"Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu.","body":[["Jika Anda membeli dengan ",["market order","market-order"],", Anda membayar di harga ask. Jika langsung menjual dengan market order, Anda menerima harga bid. Selisih keduanya adalah biaya tersembunyi yang Anda tanggung di luar ",["biaya trading","maker-taker-fees"]," resmi exchange."],["Spread biasanya sempit pada pasangan besar dan likuid seperti ",["BTC","bitcoin"],"/",["USDT","usdt"]," di exchange besar, dan lebar pada koin kecil, pasangan mata uang lokal yang sepi, atau saat pasar bergejolak. ",["Market maker","market-maker"]," membantu mempersempit spread dengan terus memasang order di kedua sisi."],["Spread sering dinyatakan dalam persen: (ask - bid) / harga tengah. Membandingkan spread antar exchange sama pentingnya dengan membandingkan biaya maker dan taker, terutama jika Anda sering bertransaksi atau memperdagangkan ",["altcoin","altcoin"],"."]],"example":"Misalkan di sebuah pasangan altcoin, bid tertinggi 1,980 USDT dan ask terendah 2,020 USDT. Spread-nya 0,040 USDT, atau sekitar 2% dari harga tengah 2,000. Jika Anda membeli 500 koin dengan market order di 2,020 lalu langsung menjual di 1,980, Anda rugi 500 x 0,040 = 20 USDT hanya dari spread, sebelum biaya trading.","mistakes":["Hanya membandingkan biaya trading tanpa melihat spread antar exchange.","Memakai market order pada koin dengan spread lebar.","Bertransaksi tepat saat rilis berita besar ketika spread bisa melebar tiba-tiba."],"faq":[{"q":"Apa penyebab spread lebar?","a":"Spread melebar ketika likuiditas rendah, sedikit market maker aktif, atau pasar sedang sangat volatil. Koin kecil dan pasangan sepi biasanya punya spread lebih lebar."},{"q":"Bagaimana mengurangi biaya spread?","a":"Gunakan pasangan yang likuid, pakai limit order di dalam spread jika memungkinkan, dan hindari bertransaksi saat pasar sedang sangat bergejolak."}],"title":"Apa itu bid-ask spread? Arti spread di kripto","description":"Pelajari arti bid-ask spread, kenapa spread adalah biaya tersembunyi, cara menghitungnya dalam persen, dan cara menekannya.","related":[["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["market-maker","Market maker","Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread."],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"id","term":"Slippage","aka":["selip harga","toleransi slippage"],"short":"Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi.","body":[["Slippage terjadi karena dua hal utama. Pertama, ",["likuiditas","liquidity"]," tipis: order Anda lebih besar daripada jumlah yang tersedia di harga terbaik, sehingga ikut memakan level harga berikutnya. Kedua, harga bergerak cepat antara saat Anda menekan tombol dan saat order dieksekusi."],["Di ",["exchange terpusat","centralized-exchange"],", slippage paling terasa pada ",["market order","market-order"]," dan stop market. Di ",["DEX","dex"]," yang memakai ",["AMM","amm"],", harga bergeser mengikuti rumus pool, sehingga order besar terhadap pool kecil bisa mengalami price impact besar. Karena itu DEX meminta Anda menyetel toleransi slippage, misalnya 0,5% atau 1%."],["Toleransi slippage yang terlalu tinggi di DEX membuka peluang serangan sandwich, di mana bot membeli sebelum Anda dan menjual sesudah Anda. Toleransi terlalu rendah membuat transaksi sering gagal, sementara ",["biaya gas","gas-fee"]," tetap terpakai."]],"example":"Misalkan Anda ingin membeli token di DEX senilai 2.000 USDC saat harga tampil 0,80 USDC, sehingga Anda berharap mendapat 2.500 token. Karena pool kecil, harga rata-rata eksekusi menjadi 0,824 USDC dan Anda hanya menerima sekitar 2.427 token. Slippage-nya 3%. Jika toleransi slippage Anda 1%, transaksi ini akan dibatalkan otomatis, bukan dieksekusi di harga yang lebih buruk.","mistakes":["Menyetel toleransi slippage 10% atau lebih di DEX hanya agar transaksi cepat berhasil.","Memakai market order besar di pasangan dengan order book tipis.","Mengira harga yang tampil di layar pasti menjadi harga eksekusi."],"faq":[{"q":"Berapa toleransi slippage yang wajar?","a":"Untuk pasangan besar dan likuid, 0,1% sampai 0,5% sering cukup. Token kecil atau sangat volatil mungkin butuh lebih, tetapi makin tinggi toleransi makin besar risiko harga buruk."},{"q":"Bagaimana cara mengurangi slippage?","a":"Gunakan limit order, pecah order besar menjadi beberapa bagian, pilih pasangan yang likuid, dan hindari bertransaksi saat pasar sedang sangat bergejolak."}],"title":"Apa itu slippage? Arti dan cara menguranginya","description":"Arti slippage di trading kripto, penyebabnya di CEX dan DEX, cara menyetel toleransi slippage, dan cara menekan kerugiannya.","related":[["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["amm","AMM (automated market maker)","AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"id","term":"Trailing stop","aka":["trailing stop loss","stop berjalan"],"short":"Trailing stop adalah stop order yang otomatis mengikuti harga ketika bergerak menguntungkan Anda dengan jarak tetap, lalu menutup posisi ketika harga berbalik sejauh jarak itu.","body":[["Anda menentukan jarak trailing, dalam persen atau angka harga. Untuk posisi long, level stop naik setiap kali harga membuat puncak baru, tetapi tidak pernah turun. Ketika harga turun dari puncak sebesar jarak yang ditentukan, order penutupan dikirim, biasanya sebagai ",["market order","market-order"],"."],"Trailing stop membantu mengunci keuntungan dalam tren tanpa harus menebak puncak. Banyak exchange juga menyediakan harga aktivasi, sehingga trailing baru mulai bekerja setelah harga mencapai level tertentu.",["Pemilihan jarak sangat penting. Jarak terlalu sempit membuat posisi tertutup oleh fluktuasi kecil, jarak terlalu lebar menyerahkan banyak keuntungan sebelum tertutup. Sesuaikan jarak dengan ",["volatilitas","volatility"]," aset, dan ingat bahwa eksekusi market bisa mengalami ",["slippage","slippage"],"."]],"example":["Misalkan Anda long ",["BTC","bitcoin"]," di 58.000 ",["USDT","usdt"]," dan memasang trailing stop 4%. Awalnya stop berada di 55.680 USDT. Harga naik ke 66.000 USDT, sehingga stop ikut naik ke 63.360 USDT. Kemudian harga turun dan menyentuh 63.360, posisi tertutup. Untuk 0,1 BTC, keuntungan Anda sekitar (63.360 - 58.000) x 0,1 = 536 USDT sebelum biaya dan slippage."],"mistakes":["Memakai jarak trailing 1% pada altcoin yang biasa bergerak 5% per jam.","Mengira trailing stop juga bergerak turun mengikuti harga pada posisi long.","Lupa bahwa trailing stop biasanya dieksekusi sebagai market order yang bisa slippage."],"faq":[{"q":"Apakah trailing stop lebih baik dari stop loss biasa?","a":"Trailing stop lebih cocok untuk mengikuti tren dan mengunci keuntungan. Stop loss biasa lebih sederhana untuk membatasi kerugian di level tetap. Banyak trader memakai keduanya sesuai situasi."},{"q":"Berapa persen trailing stop yang ideal?","a":"Tidak ada angka universal. Banyak trader memakai jarak yang sedikit lebih besar dari pergerakan normal aset dalam timeframe yang mereka perdagangkan."}],"title":"Apa itu trailing stop? Arti dan contoh perhitungannya","description":"Pelajari arti trailing stop, cara stop mengikuti harga untuk mengunci untung, dan cara memilih jarak trailing yang sesuai.","related":[["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan."],["stop-limit-order","Stop limit order","Stop limit order adalah order yang aktif saat harga menyentuh harga stop, lalu otomatis memasang limit order di harga limit yang Anda tentukan."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit dan stop-loss adalah rencana, bukan asuransi"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"id","term":"Mark price (harga tanda)","aka":["mark price","harga mark","harga wajar"],"short":"Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures.","body":[[["Harga transaksi terakhir","last-price"]," di satu exchange bisa melonjak sesaat karena order besar atau ",["order book","order-book"]," tipis. Jika ",["likuidasi","liquidation"]," memakai harga itu, banyak trader akan dilikuidasi secara tidak adil. Karena itu, exchange memakai mark price yang lebih stabil dan sulit dimanipulasi."],["Rumus mark price berbeda tiap exchange, tetapi umumnya menggabungkan ",["harga indeks","index-price"],", yaitu rata-rata harga spot dari beberapa exchange besar, dengan komponen basis atau funding yang dirata-ratakan. Hasilnya, mark price biasanya sangat dekat dengan harga terakhir, tetapi tidak ikut melonjak saat terjadi wick ekstrem di satu pasar."],["Di aplikasi exchange, Anda bisa memilih apakah ",["stop loss","stop-loss"]," dipicu oleh harga terakhir atau mark price. Pilihan ini memengaruhi seberapa sensitif order Anda terhadap lonjakan singkat."]],"example":["Misalkan ",["BTC","bitcoin"]," perpetual di sebuah exchange tiba-tiba turun dari 61.000 ke 59.500 USDT dalam beberapa detik karena satu market order jual besar, lalu kembali ke 60.950. Sementara itu, harga indeks dari beberapa exchange spot hanya turun ke 60.800, sehingga mark price juga sekitar 60.800. Posisi long dengan harga likuidasi 60.000 tidak dilikuidasi, karena mark price tidak pernah menyentuhnya meski harga terakhir sempat jatuh 1.500 USDT."],"mistakes":["Membandingkan harga likuidasi dengan harga terakhir di grafik, bukan dengan mark price.","Tidak memeriksa pemicu stop loss, apakah harga terakhir atau mark price.","Mengira mark price adalah harga di mana Anda bisa bertransaksi, padahal order tetap dieksekusi di order book."],"faq":[{"q":"Apa beda mark price dan last price?","a":"Last price adalah harga transaksi terakhir di exchange itu. Mark price adalah harga acuan yang lebih stabil, dihitung dari harga indeks, dan dipakai untuk PnL belum terealisasi serta likuidasi."},{"q":"Kenapa unrealized PnL saya berbeda dari perhitungan dengan harga terakhir?","a":"Karena kebanyakan exchange menghitung unrealized PnL memakai mark price. Selisih kecil antara mark price dan harga terakhir membuat angkanya sedikit berbeda."}],"title":"Apa itu mark price di futures kripto? Arti dan fungsinya","description":"Pahami mark price di futures kripto: cara dihitung dari harga indeks, kenapa dipakai untuk likuidasi, dan bedanya dengan last price.","related":[["index-price","Harga indeks (index price)","Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures."],["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin."],["last-price","Harga terakhir (last traded price)","Harga terakhir adalah harga transaksi paling akhir yang benar-benar terjadi di order book sebuah exchange, dan biasanya inilah angka yang Anda lihat di grafik dan daftar pasar."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"id","term":"Convert (tukar instan)","aka":["Convert","instant swap","tukar instan","konversi"],"short":"Convert adalah fitur bursa untuk menukar satu aset kripto ke aset lain secara instan dengan harga yang dikunci beberapa detik, tanpa perlu memasang order di order book.","body":[["Anda cukup memilih aset asal, aset tujuan, dan jumlah. Bursa menampilkan kurs, lalu Anda punya beberapa detik untuk mengonfirmasi. Fitur ini memudahkan pemula karena tidak perlu memahami ",["limit order","limit-order"],", ",["market order","market-order"],", atau ",["pasangan perdagangan","trading-pair"],"."],["Banyak bursa menulis tanpa biaya untuk Convert, tetapi biayanya biasanya tersirat di kurs. Kurs Convert sering sedikit lebih buruk daripada harga terbaik di ",["order book","order-book"],". Untuk koin dengan ",["likuiditas","liquidity"]," rendah, selisihnya bisa lebih lebar."],["Convert juga berguna untuk menukar aset tanpa pasangan langsung, misalnya dari satu ",["altcoin","altcoin"]," ke altcoin lain, karena sistem mengatur rutenya. Untuk jumlah besar atau transaksi rutin, bandingkan hasilnya dengan order di pasar spot."]],"example":"Misalkan Anda ingin menukar 1.000 USDT ke SOL. Di pasar spot, harga ask terbaik 150,00 USDT dan biaya taker 0,1%. Lewat market order Anda menerima sekitar 6,667 SOL dikurangi biaya 0,0067, jadi sekitar 6,660 SOL. Fitur Convert menampilkan kurs 150,60 tanpa biaya, sehingga Anda menerima sekitar 6,640 SOL. Selisihnya 0,020 SOL, kira-kira 3 USDT. Untuk transaksi kecil sekali-kali, perbedaan ini mungkin sepadan dengan kemudahannya, tetapi untuk transaksi rutin biayanya bertambah.","mistakes":["Percaya label tanpa biaya tanpa membandingkan jumlah akhir yang diterima.","Menukar jumlah besar lewat Convert untuk koin yang likuiditasnya tipis.","Membiarkan kurs kedaluwarsa lalu mengonfirmasi ulang tanpa melihat kurs baru."],"faq":[{"q":"Apakah Convert benar-benar gratis?","a":"Sering tidak ada biaya tertulis, tetapi bursa mengambil margin lewat kurs yang sedikit lebih buruk dari harga pasar. Bandingkan jumlah akhir yang Anda terima."},{"q":"Kapan lebih baik memakai Convert daripada trading spot?","a":"Convert cocok untuk transaksi kecil, aset tanpa pasangan langsung, atau saat Anda belum paham order book. Untuk jumlah besar, limit order di spot biasanya lebih efisien."}],"title":"Apa itu fitur Convert di bursa kripto? Tukar instan","description":"Pahami cara kerja fitur Convert atau tukar instan, biaya yang tersembunyi di kurs, dan kapan sebaiknya memakai spot.","related":[["spot-trading","Spot trading (perdagangan spot)","Spot trading adalah jual beli aset kripto secara langsung di harga pasar saat ini, di mana aset benar-benar berpindah ke akun Anda setelah transaksi selesai."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Perdagangan spot pertamamu: dari 100 jadi 0.002 BTC"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"id","term":"Saham tokenisasi (tokenized stocks)","aka":["tokenized stocks","saham ter-tokenisasi","token saham"],"short":"Saham tokenisasi adalah token di blockchain yang mewakili atau mengikuti harga saham nyata, seperti saham perusahaan AS, sehingga bisa diperdagangkan di platform kripto, sering 24 jam.","body":["Biasanya ada penerbit yang membeli saham asli lewat broker atau kustodian, lalu menerbitkan token dengan rasio 1:1 terhadap saham itu. Ada juga produk yang hanya mengikuti harga tanpa memberi kepemilikan langsung. Struktur hukum, hak dividen, dan hak suara berbeda per penerbit.",["Daya tariknya: bisa membeli pecahan saham, bertransaksi dengan ",["USDT","usdt"]," atau ",["USDC","usdc"],", dan memindahkan token ke dompet atau protokol ",["DeFi","defi"]," tertentu. Namun pemegang token sering tidak tercatat sebagai pemegang saham resmi, dan tidak semua token bisa ditukar kembali ke saham asli oleh pengguna biasa."],["Produk ini sering dibatasi untuk wilayah tertentu, termasuk Amerika Serikat, karena aturan sekuritas. Di luar jam bursa saham, harga token bisa menyimpang dari ",["harga terakhir","last-price"]," saham karena ",["likuiditas","liquidity"]," terbatas. Cek siapa penerbitnya, di mana saham disimpan, dan apa hak Anda."]],"example":"Misalkan sebuah saham AS ditutup di 200 dolar pada Jumat. Di akhir pekan, saat bursa saham tutup, token sahamnya diperdagangkan antara 196 dan 205 USDT karena kabar baru dan likuiditas tipis. Anda membeli 0,5 token di 204 USDT, membayar 102 USDT. Senin pagi saham dibuka di 199 dolar dan harga token kembali ke sekitar 199, sehingga posisi Anda bernilai 99,5 USDT, rugi 2,5 USDT. Selisih seperti ini wajar terjadi di luar jam pasar.","mistakes":["Mengira memegang token saham sama dengan tercatat sebagai pemegang saham resmi.","Berdagang dalam jumlah besar di luar jam bursa saat likuiditas tipis.","Tidak mengecek penerbit, kustodian, dan hak dividen sebelum membeli."],"faq":[{"q":"Apakah saham tokenisasi memberi dividen?","a":"Tergantung penerbitnya. Sebagian meneruskan nilai dividen kepada pemegang token, sebagian lagi tidak, jadi cek dokumen produk."},{"q":"Apa beda saham tokenisasi dan stock perpetual?","a":"Saham tokenisasi mewakili atau mengikuti saham dengan model penerbitan aset, tanpa leverage. Stock perpetual adalah kontrak derivatif dengan leverage dan funding rate, tanpa kepemilikan saham."}],"title":"Apa itu saham tokenisasi? Saham di blockchain","description":"Pelajari cara kerja saham tokenisasi, hak pemegang token, perbedaan harga di luar jam bursa, dan risikonya.","related":[["stock-perpetuals","Perpetual saham (stock perpetuals)","Perpetual saham adalah kontrak berjangka perpetual tanpa tanggal jatuh tempo yang mengikuti harga saham atau indeks saham, diperdagangkan dengan margin dan leverage di bursa kripto atau perp DEX."],["real-world-assets","Real World Assets (RWA, aset dunia nyata)","Real World Assets (RWA) adalah aset dari dunia keuangan nyata, seperti surat utang negara, kredit, properti, emas, atau saham, yang kepemilikannya direpresentasikan sebagai token di blockchain."],["spot-bitcoin-etf","ETF Bitcoin spot","ETF Bitcoin spot adalah reksa dana yang diperdagangkan di bursa saham dan memegang bitcoin asli sebagai aset dasarnya, sehingga harga sahamnya mengikuti harga BTC."],["usdc","USDC (USD Coin)","USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
